SET local check_function_bodies = off;

CREATE EXTENSION "pgjwt" SCHEMA "extensions";

CREATE TABLE "public"."anime" (
  "id"           bigint                      GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "jp_title"     text,
  "kr_title"     text                        NOT NULL,
  "en_title"     text,
  "kr_sub_title" text,
  "created_at"   timestamp without time zone NOT NULL DEFAULT now(),
  "updated_at"   timestamp without time zone,
  "type"         character varying           NOT NULL DEFAULT 'anime'::character varying,
  CONSTRAINT "anime_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."anime"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."gacha" (
  "id"         bigint                   NOT NULL,
  "created_at" timestamp with time zone,
  "updated_at" text,
  "name"       text,
  "name_kr"    text,
  "image_link" text,
  "anime_id"   bigint,
  "price"      bigint,
  CONSTRAINT "gacha_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."gacha"
  ADD CONSTRAINT "gacha_anime_id_fkey" FOREIGN KEY (anime_id) REFERENCES public.anime(id);

CREATE POLICY "anonymous_user_crud 1twvzjd_2" ON "storage"."objects"
  FOR UPDATE
  TO "anon"
  USING ((bucket_id = 'profile'::text));

CREATE POLICY "anonymous_user_crud 1twvzjd_3" ON "storage"."objects"
  FOR DELETE
  TO "anon"
  USING ((bucket_id = 'profile'::text));

COMMENT ON EXTENSION "pgjwt" IS 'JSON Web Token API for Postgresql';

COMMENT ON TABLE "public"."anime" IS '애니메이션 목록';

REVOKE ALL ON SEQUENCE "public"."anime_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."anime_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."anime_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."anime_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."anime_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."anime_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."anime_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."anime_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."anime" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."anime" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."anime" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."anime" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."gacha" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."gacha" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."gacha" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."gacha" TO "service_role";

